#include <bits/stdc++.h>
using namespace std;

const int MAX = 200005;
const int INF = 1000000007;

long long a, b, c, minNumerator = -1, minDenominator = -1;
long long X, Y, N;

void check (long long numerator, int denominator) {
    if (numerator < 0) return;
    if (minNumerator == -1) {
        minNumerator = numerator;
        minDenominator = denominator;
        return;
    }
    long long diffA = abs(minDenominator * X - minNumerator * Y) * denominator;
    long long diffB = abs(denominator * X - numerator * Y) * minDenominator;
    if (diffA > diffB) {
        minNumerator = numerator;
        minDenominator = denominator;
    } else if (diffA == diffB && (denominator < minDenominator || (denominator == minDenominator && numerator < minNumerator))) {
        minNumerator = numerator;
        minDenominator = denominator;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> X >> Y >> N;
    for (int i = 1; i <= N; ++i) {
        long long val = i * X / Y;
        check(val - 1, i);
        check(val, i);
        check(val + 1, i);
    }
    cout << minNumerator << "/" << minDenominator;
    return 0;
}
